/** ¿Parece una factura? Sirve para avisar cuando se cuela otro documento. */
export function looksLikeInvoice(text) {
  const low = fold(text);
  const hits = [
    /factura/, /total/, /base imponible/, /igic|iva/, /\d{1,3}[.,]\d{2}/, /cif|nif/,
  ].filter((re) => re.test(low)).length;
  return hits >= 3;
}

